        add.accept(Chronicle.key("board_founded", 2), "The Leviathans founded their Board. To the new chain, every other faction was livestock.");
        add.accept(Chronicle.key("dick_fell", 0), "%1$s, founder of the Board, was slain in his own penthouse. His chair awaited a successor.");
        add.accept(Chronicle.key("dick_fell", 1), "The first Lord, %1$s, fell at the top of SucroCorp. The Board survived its founder.");
        add.accept(Chronicle.key("dick_fell", 2), "%1$s was slain in his penthouse boardroom; the founder's place at the table stood empty.");
        add.accept(Chronicle.key("front_landing", 0), "%1$s led the Leviathans into %3$s and seized a foothold on the front.");
