        add.accept("chain.supernaturalcraft.penthouse.rise.0", "Welcome to the top floor. I trust you have brought something to the table.");
        add.accept("chain.supernaturalcraft.penthouse.rise.1", "Do come in. I have cleared my schedule, and I have not eaten.");
